chapter(2, 'Room board and housekeeping tasks', 'Read the phone room board, then follow a cleaning task as the room attendant.', 'Aarav (Reception)', 'reception', menu='Rooms', display='mobile')
click('btn:Rooms', 'Tap the Rooms tab.', 'The board is the reception\'s main view.', expect='The Room board opens.', check="ctx.page==='rooms'")
read('The chips All, Occupied, Ready, Dirty, Cleaning, Inspection and Blocked filter the board, and the floor tabs narrow it to one floor. Each room is a card with its number, type and state.', 'Colours always come with a word.', target='btn:Dirty', expect='The status chips.')
click('btn:Dirty', 'Tap Dirty.', 'Housekeeping works from this list.', expect='Only dirty rooms are shown.')
click('btn:All', 'Tap All again.', 'Return the filter to All before leaving.', expect='All rooms are shown.')
step('Ravi, the room attendant, opens Housekeeping & Maintenance, then Housekeeping. He sees only My tasks, grouped by floor section.', 'An attendant sees only their own rooms and no hotel money.', target='sel:main', auto=['user:housekeeper', 'click:menutop:Housekeeping & Maintenance', 'click:menuleaf:Housekeeping'], action='click', expect='The task cards of Ravi open.', check="ctx.page==='housekeeping'")
click('btn:Start cleaning', 'Tap Start cleaning on the first card.', 'Starting starts the timer of the room.', expect='The card shows the checklist.', check="has('Complete cleaning')")
step('Tick the checklist items: Linen & bathroom, Surfaces & amenities and Final room check.', 'Complete cleaning stays grey until every item is ticked.', target='btn:Complete cleaning', auto=['check:field:Linen', 'check:field:Surfaces', 'check:field:Final room check'], action='click', expect='All items are ticked.')
click('btn:Complete cleaning', 'Tap Complete cleaning.', 'The room waits for the supervisor\'s inspection.', expect='The task moves to Awaiting inspection.')
click('btn:Report repair', 'Tap Report repair on a card.', 'A fault found while cleaning is reported at once.', expect='The Report a repair sheet opens.', check="has('Report a repair')")
typ('field:What needs repair', 'Tap in the shower drips', 'Describe the fault: Tap in the shower drips.', 'Maintenance reads this text.', expect='The fault is described.')
click('modalbtn:Report repair', 'Tap Report repair.', 'Maintenance gets the request.', expect='The repair is reported.')
